//! Single producer / single real-time consumer. No allocation or lock in pop().
use std::{cell::UnsafeCell,sync::atomic::{AtomicBool,AtomicUsize,Ordering}};
pub struct Ring {data:Box<[UnsafeCell<f32>]>,read:AtomicUsize,write:AtomicUsize,pub output:AtomicUsize,pub last_audio:AtomicUsize,pub cancelled:AtomicBool,pub failed:AtomicBool}
// Exactly one producer and one consumer; release/acquire transfers slot ownership.
unsafe impl Sync for Ring{}
impl Ring {
 pub fn new(capacity:usize)->Self{assert!(capacity>0);Self{data:(0..capacity).map(|_|UnsafeCell::new(0.)).collect(),read:AtomicUsize::new(0),write:AtomicUsize::new(0),output:AtomicUsize::new(0),last_audio:AtomicUsize::new(0),cancelled:AtomicBool::new(false),failed:AtomicBool::new(false)}}
 pub fn played(&self)->usize{self.read.load(Ordering::Acquire)}
 pub fn buffered(&self)->usize{self.write.load(Ordering::Acquire).wrapping_sub(self.read.load(Ordering::Acquire))}
 pub fn push(&self,input:&[f32])->usize{if self.cancelled.load(Ordering::Acquire){return 0}let w=self.write.load(Ordering::Relaxed);let r=self.read.load(Ordering::Acquire);let n=input.len().min(self.data.len()-w.wrapping_sub(r));for(i,v)in input[..n].iter().enumerate(){unsafe{*self.data[(w+i)%self.data.len()].get()=*v}}self.write.store(w.wrapping_add(n),Ordering::Release);n}
 pub fn pop(&self,out:&mut[f32]){let base=self.output.fetch_add(out.len(),Ordering::Relaxed);if self.cancelled.load(Ordering::Acquire){out.fill(0.);return}let r=self.read.load(Ordering::Relaxed);let w=self.write.load(Ordering::Acquire);let n=out.len().min(w.wrapping_sub(r));for(i,v)in out[..n].iter_mut().enumerate(){*v=unsafe{*self.data[(r+i)%self.data.len()].get()}}out[n..].fill(0.);if n>0{self.last_audio.store(base+n,Ordering::Release)}self.read.store(r.wrapping_add(n),Ordering::Release);}
}
#[cfg(test)]mod tests{use super::*;use std::sync::Arc;#[test]fn wraps_and_cancellation_silences(){let r=Ring::new(3);assert_eq!(r.push(&[1.,2.,3.,4.]),3);let mut a=[0.;2];r.pop(&mut a);assert_eq!(a,[1.,2.]);assert_eq!(r.push(&[4.,5.]),2);let mut b=[0.;4];r.pop(&mut b);assert_eq!(b,[3.,4.,5.,0.]);r.push(&[9.]);r.cancelled.store(true,Ordering::Release);r.pop(&mut a);assert_eq!(a,[0.,0.]);}#[test]fn concurrent_order_is_preserved(){let r=Arc::new(Ring::new(997));let producer=r.clone();let t=std::thread::spawn(move||{for i in 1..100001{while producer.push(&[i as f32])==0{std::thread::yield_now()}}});let mut values=0;while values<100000{let before=r.played();let mut a=[0.;131];r.pop(&mut a);let n=r.played()-before;for v in &a[..n]{values+=1;assert_eq!(*v,values as f32)}std::thread::yield_now()}t.join().unwrap();assert_eq!(r.buffered(),0);}
#[test]fn timeline_includes_device_silence_but_not_fake_speech_progress(){let r=Ring::new(4);r.pop(&mut[0.;7]);assert_eq!(r.played(),0);r.push(&[1.,2.]);r.pop(&mut[0.;4]);assert_eq!(r.played(),2);assert_eq!(r.output.load(Ordering::Acquire),11);assert_eq!(r.last_audio.load(Ordering::Acquire),9);r.pop(&mut[0.;4]);assert_eq!(r.last_audio.load(Ordering::Acquire),9);}}
